const $=id=>document.getElementById(id);
let reverse=false,mode='text',manualText='',loadedFile=null,fileResult=null,operation=0,busy=false;
const count=s=>Array.from(s).length;
const fileEngine=()=>import('./file-engine.mjs?v=7');
function update(){const value=$('input').value;$('output').value=convert(value,reverse);$('input-count').textContent=`${count(value)} belgi · ${value.trim()?value.trim().split(/\s+/).length:0} so‘z`;$('output-count').textContent=`${count($('output').value)} belgi`;$('copy').disabled=$('download').disabled=!value;$('status').textContent=value?'Tayyor · Matn o‘girildi':'Yozishni boshlang';}
function labels(){ $('input-label').textContent=reverse?'Yangi yozuv':'Amaldagi yozuv';$('output-label').textContent=reverse?'Amaldagi yozuv':'Yangi yozuv';$('output').placeholder=reverse?'Amaldagi yozuvdagi matningiz shu yerda ko‘rinadi…':'Yangi yozuvdagi matningiz shu yerda ko‘rinadi…';$('input').placeholder=mode==='file'?'Hujjatingizdagi matn shu yerda ko‘rinadi…':'Matningizni shu yerga yozing yoki joylashtiring…';}
function setMode(value){if(value===mode)return;if(mode==='text')manualText=$('input').value;mode=value;$('converter').classList.toggle('file-mode',mode==='file');$('file-workspace').hidden=mode!=='file';for(const id of ['text','file']){$(id+'-mode').classList.toggle('selected',mode===id);$(id+'-mode').setAttribute('aria-pressed',String(mode===id));}$('input').readOnly=mode==='file';$('input').value=mode==='file'?(loadedFile?.text||''):manualText;labels();update();}
function progress(value,message){$('file-progress').value=value;$('file-status').textContent=message;}
function setBusy(value){busy=value;$('choose-file').disabled=value;$('save-file').disabled=value||!fileResult;$('forward').disabled=$('reverse').disabled=value;$('file-workspace').setAttribute('aria-busy',String(value));}
function resetFile(){operation++;loadedFile=null;fileResult=null;setBusy(false);$('file-input').value='';$('file-state').hidden=$('file-ready').hidden=$('file-error').hidden=$('file-warning').hidden=true;if(mode==='file'){$('input').value='';update();}}
function showError(e){$('file-error').textContent=e instanceof TypeError?'Faylni o‘qib bo‘lmadi. Formatini tekshiring yoki sahifani yangilab qayta urinib ko‘ring.':(e.message||'Faylni qayta ishlashda xatolik yuz berdi.');$('file-error').hidden=false;}
async function renderFile(token=++operation){if(!loadedFile)return;fileResult=null;$('file-error').hidden=true;$('file-ready').hidden=true;setBusy(true);progress(0,'Matn o‘girilmoqda…');try{const engine=await fileEngine();const result=await engine.convertFile(loadedFile,reverse,(n,m)=>{if(token===operation)progress(n,m);});if(token!==operation)return;fileResult=result;const warnings=[...(loadedFile.warnings||[]),...(result.warnings||[])];$('file-warning').textContent=warnings.join(' ');$('file-warning').hidden=!warnings.length;if(mode==='file'){$('input').value=loadedFile.text;update();}$('save-file-label').textContent=`${loadedFile.ext.toUpperCase()} yuklab olish`;$('file-result-description').textContent=loadedFile.ext==='pdf'?`PDF tayyor · ${result.pages} sahifa. Matn yangi maketga joylandi; asl rasmlar va jadvallar maketi saqlanmaydi.`:loadedFile.zip?'Hujjatdagi matn o‘girildi. Quyida asosiy matn ko‘rsatilgan.':'Matn o‘girildi. Natija TXT shaklida yuklab olinadi.';$('file-ready').hidden=false;progress(100,'Tayyor · Hujjat o‘girildi');}catch(e){if(token===operation){showError(e);progress(0,'O‘girish tugallanmadi');}}finally{if(token===operation)setBusy(false);}}
async function chooseFile(file){if(!file)return;setMode('file');resetFile();const token=++operation;$('file-state').hidden=false;$('file-name').textContent=file.name;$('file-meta').textContent=`${(file.size/1024/1024).toFixed(2)} MB · Faqat qurilmangizda`;setBusy(true);progress(0,'Fayl ochilmoqda…');try{const engine=await fileEngine();const doc=await engine.readFile(file,(n,m)=>{if(token===operation)progress(n,m);});if(token!==operation)return;loadedFile=doc;$('file-meta').textContent=`${doc.ext.toUpperCase()} · ${(file.size/1024/1024).toFixed(2)} MB${doc.pages?' · '+doc.pages+(doc.ext==='pptx'?' slayd':' sahifa'):''}`;if(doc.warnings.length){$('file-warning').textContent=doc.warnings.join(' ');$('file-warning').hidden=false;}await renderFile(token);}catch(e){if(token===operation){showError(e);progress(0,'Fayl o‘qilmadi');setBusy(false);}}}
function direction(value){reverse=value;for(const [id,on] of [['forward',!value],['reverse',value]]){$(id).classList.toggle('active',on);$(id).setAttribute('aria-pressed',String(on));}labels();update();if(loadedFile)renderFile();}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('input').addEventListener('input',()=>{if(mode==='text')manualText=$('input').value;update();});$('forward').onclick=()=>direction(false);$('reverse').onclick=()=>direction(true);$('text-mode').onclick=()=>setMode('text');$('file-mode').onclick=()=>setMode('file');
$('clear').onclick=()=>{$('input').value='';manualText='';update();$('input').focus();};$('example').onclick=()=>{const sample='O‘zbekiston — go‘zal o‘lka. Shaharlar, bog‘lar va ochiq ko‘ngilli insonlar.\nHar bir o‘zgarish yangi imkoniyat!';$('input').value=reverse?convert(sample):sample;manualText=$('input').value;update();};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('output').value);$('status').textContent='Nusxa olindi!';}catch{$('output').focus();$('output').select();$('status').textContent='Nusxa olish uchun Ctrl+C yoki ⌘C bosing.';}};$('download').onclick=()=>{download(new Blob([$('output').value],{type:'text/plain;charset=utf-8'}),'alifbo-matn.txt');$('status').textContent='TXT fayl tayyor';};
$('choose-file').onclick=()=>$('file-input').click();$('file-input').onchange=e=>{chooseFile(e.target.files[0]);e.target.value='';};$('remove-file').onclick=resetFile;$('save-file').onclick=()=>{if(fileResult&&!busy)download(fileResult.blob,fileResult.filename);};
let dragDepth=0;$('dropzone').addEventListener('dragenter',e=>{e.preventDefault();dragDepth++;if(!busy)$('dropzone').classList.add('dragging');});$('dropzone').addEventListener('dragover',e=>e.preventDefault());$('dropzone').addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;$('dropzone').classList.remove('dragging');}});$('dropzone').addEventListener('drop',e=>{e.preventDefault();dragDepth=0;$('dropzone').classList.remove('dragging');if(!busy){if(e.dataTransfer.files.length>1){$('file-error').textContent='Bir vaqtning o‘zida bitta hujjat tanlang.';$('file-error').hidden=false;}else chooseFile(e.dataTransfer.files[0]);}});
update();
